        var off = isObj && !!opt.disabled;
        var row = document.createElement("div");
        row.className = "pg-input__option"
          + (value === spec.value ? " pg-input__option--selected" : "")
          + (desc ? " pg-input__option--rich" : "")
          + (code != null ? " pg-input__option--coded" : "")
