      var glass = document.createElement("i");
      glass.className = "ti ti-search";
      var box = document.createElement("input");
      box.className = "pg-input__panel-search-input";
      box.type = "text";
      // Through the Peg's own catalogue (`translations = Translations(...)`,
      // read by `_t`), so an app that translates its UI can translate the
      // picker's two words too, instead of every panel saying them in
      // English. The English is only the fallback when no catalogue names
